const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');

function deferred() {
  let resolve, reject;
  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
  return { promise, resolve, reject };
}

function fixture(ttlMs = 100) {
  const loads = [];
  let time = 0;
  const cache = createCache({
    ttlMs,
    now: () => time,
    load(key) {
      const gate = deferred();
      loads.push({ key, ...gate });
      return gate.promise;
    }
  });
  return { cache, loads, advance: value => { time = value; } };
}

for (const mutation of ['invalidate', 'clear']) {
  for (const order of ['old first', 'new first']) {
    test(`${mutation}: obsolete success, ${order}`, async () => {
      const { cache, loads } = fixture();
      const old = cache.get('key');
      await Promise.resolve();
      cache[mutation]('key');
      const fresh = cache.get('key');
      await Promise.resolve();
      assert.equal(loads.length, 2);
      if (order === 'old first') {
        loads[0].resolve('old');
        assert.equal(await old, 'old');
        assert.equal(cache.size, 0);
        const joined = cache.get('key');
        await Promise.resolve();
        assert.equal(loads.length, 2);
        loads[1].resolve('new');
        assert.equal(await joined, 'new');
      } else {
        loads[1].resolve('new');
        assert.equal(await fresh, 'new');
        loads[0].resolve('old');
        assert.equal(await old, 'old');
      }
      assert.equal(await fresh, 'new');
      assert.equal(await cache.get('key'), 'new');
      assert.equal(cache.size, 1);
    });
  }

  test(`${mutation}: obsolete rejection preserves newer flight`, async () => {
    const { cache, loads } = fixture();
    const reason = { obsolete: true };
    const old = cache.get('key');
    const oldResult = assert.rejects(old, error => error === reason);
    await Promise.resolve();
    cache[mutation]('key');
    const fresh = cache.get('key');
    await Promise.resolve();
    loads[0].reject(reason);
    await oldResult;
    const joined = cache.get('key');
    await Promise.resolve();
    assert.equal(loads.length, 2);
    loads[1].resolve('new');
    assert.equal(await fresh, 'new');
    assert.equal(await joined, 'new');
  });
}

test('repeated invalidations are distinct barriers without stored values', async () => {
  const { cache, loads } = fixture();
  const readers = [];
  for (let i = 0; i < 3; i++) {
    readers.push(cache.get('key'));
    await Promise.resolve();
    if (i < 2) cache.invalidate('key');
  }
  loads[1].resolve('middle');
  assert.equal(await readers[1], 'middle');
  loads[0].resolve('first');
  assert.equal(await readers[0], 'first');
  assert.equal(cache.size, 0);
  const joined = cache.get('key');
  await Promise.resolve();
  assert.equal(loads.length, 3);
  loads[2].resolve('last');
  assert.equal(await readers[2], 'last');
  assert.equal(await joined, 'last');
});

test('set wins without obsolete completion restarting its TTL', async () => {
  const { cache, loads, advance } = fixture(10);
  const old = cache.get('key');
  await Promise.resolve();
  advance(2);
  assert.equal(cache.set('key', undefined), undefined);
  advance(8);
  loads[0].resolve('old');
  assert.equal(await old, 'old');
  assert.equal(await cache.get('key'), undefined);
  advance(12);
  assert.equal(cache.size, 0);
  const fresh = cache.get('key');
  await Promise.resolve();
  assert.equal(loads.length, 2);
  loads[1].resolve('new');
  assert.equal(await fresh, 'new');
});

test('set expiration starts a fresh flight while obsolete load is pending', async () => {
  const { cache, loads, advance } = fixture(10);
  const old = cache.get('key');
  await Promise.resolve();
  cache.set('key', 'manual');
  advance(10);
  const fresh = cache.get('key');
  await Promise.resolve();
  assert.equal(cache.size, 0);
  loads[0].resolve('old');
  assert.equal(await old, 'old');
  const joined = cache.get('key');
  await Promise.resolve();
  assert.equal(loads.length, 2);
  loads[1].resolve('new');
  assert.equal(await fresh, 'new');
  assert.equal(await joined, 'new');
});

for (const mutation of ['invalidate', 'clear', 'set']) {
  test(`synchronous loader ${mutation} detaches its own flight`, async () => {
    let calls = 0;
    const cache = createCache({ now: () => 0, load(key) {
      calls++;
      if (calls === 1) {
        cache[mutation](key, 'manual');
        return 'old';
      }
      return 'new';
    } });
    assert.equal(await cache.get('key'), 'old');
    assert.equal(await cache.get('key'), mutation === 'set' ? 'manual' : 'new');
    assert.equal(calls, mutation === 'set' ? 1 : 2);
  });
}

for (const [name, failure, reason] of [
  ['synchronous throw', () => { throw null; }, null],
  ['promise rejection', () => Promise.reject('failed'), 'failed'],
  ['thenable rejection', () => ({ then(resolve, reject) { reject(undefined); } }), undefined],
  ['throwing then getter', () => ({ get then() { throw 42; } }), 42]
]) {
  test(`${name}: all readers reject and a later read retries`, async () => {
    let calls = 0;
    const cache = createCache({ now: () => 0, load() {
      calls++;
      return calls === 1 ? failure() : 'recovered';
    } });
    const first = cache.get('key');
    const second = cache.get('key');
    await Promise.all([
      assert.rejects(first, error => Object.is(error, reason)),
      assert.rejects(second, error => Object.is(error, reason))
    ]);
    assert.equal(calls, 1);
    assert.equal(cache.size, 0);
    assert.equal(await cache.get('key'), 'recovered');
    assert.equal(calls, 2);
  });
}

test('reentrant reads join their own flight and other keys load independently', async () => {
  const calls = [];
  let joined, other;
  const cache = createCache({ now: () => 0, load(...args) {
    assert.equal(args.length, 1);
    const [key] = args;
    calls.push(key);
    if (key === 'a') {
      joined = cache.get('a');
      other = cache.get('b');
    }
    return key;
  } });
  assert.equal(await cache.get('a'), 'a');
  assert.equal(await joined, 'a');
  assert.equal(await other, 'b');
  assert.deepEqual(calls, ['a', 'b']);
});

test('TTL starts at commit and expires at the exact deadline', async () => {
  const { cache, loads, advance } = fixture(10);
  const reader = cache.get('key');
  await Promise.resolve();
  advance(20);
  loads[0].resolve(null);
  assert.equal(await reader, null);
  advance(29);
  assert.equal(await cache.get('key'), null);
  advance(30);
  const next = cache.get('key');
  await Promise.resolve();
  assert.equal(cache.size, 0);
  assert.equal(loads.length, 2);
  const joined = cache.get('key');
  await Promise.resolve();
  assert.equal(loads.length, 2);
  loads[1].resolve('new');
  assert.equal(await next, 'new');
  assert.equal(await joined, 'new');
});

test('zero TTL deduplicates only unsettled loads', async () => {
  const { cache, loads } = fixture(0);
  const first = cache.get(NaN);
  const joined = cache.get(NaN);
  await Promise.resolve();
  assert.equal(loads.length, 1);
  loads[0].resolve('first');
  assert.equal(await first, 'first');
  assert.equal(await joined, 'first');
  assert.equal(cache.size, 0);
  const next = cache.get(NaN);
  await Promise.resolve();
  assert.equal(loads.length, 2);
  loads[1].resolve('next');
  assert.equal(await next, 'next');
});

test('clear removes all values and detaches all flights without affecting another cache', async () => {
  const { cache, loads } = fixture();
  const separate = createCache({ now: () => 0, load: () => 'separate' });
  const first = cache.get('a');
  const second = cache.get('b');
  await Promise.resolve();
  cache.set('c', 'stored');
  separate.set('a', 'isolated');
  assert.equal(cache.clear(), undefined);
  loads[0].resolve('old a');
  loads[1].resolve('old b');
  assert.equal(await first, 'old a');
  assert.equal(await second, 'old b');
  assert.equal(cache.size, 0);
  assert.equal(await separate.get('a'), 'isolated');
});

