'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');

function deferred() {
  let resolve, reject;
  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
  return { promise, resolve, reject };
}

function fixture(ttlMs = 100) {
  const loads = [];
  let time = 0;
  const cache = createCache({
    ttlMs,
    now: () => time,
    load(key) {
      const gate = deferred();
      loads.push({ key, ...gate });
      return gate.promise;
    }
  });
  return { cache, loads, advance: value => { time = value; } };
}

for (const mutation of ['invalidate', 'clear']) {
  for (const order of ['old first', 'new first']) {
    test(`${mutation}: obsolete success, ${order}`, async () => {
      const { cache, loads } = fixture();
      const old = cache.get('key');
      await Promise.resolve();
      cache[mutation]('key');
      const fresh = cache.get('key');
      await Promise.resolve();
      assert.equal(loads.length, 2);
      if (order === 'old first') {
        loads[0].resolve('old');
        assert.equal(await old, 'old');
        assert.equal(cache.size, 0);
        const joined = cache.get('key');
        await Promise.resolve();
        assert.equal(loads.length, 2);
        loads[1].resolve('new');
        assert.equal(await joined, 'new');
      } else {
        loads[1].resolve('new');
        assert.equal(await fresh, 'new');
        loads[0].resolve('old');
        assert.equal(await old, 'old');
      }
      assert.equal(await fresh, 'new');
      assert.equal(await cache.get('key'), 'new');
      assert.equal(cache.size, 1);
    });
  }

  test(`${mutation}: obsolete rejection preserves newer flight`, async () => {
    const { cache, loads } = fixture();
    const reason = { obsolete: true };
    const old = cache.get('key');
    const oldResult = assert.rejects(old, error => error === reason);
    await Promise.resolve();
    cache[mutation]('key');
    const fresh = cache.get('key');
    await Promise.resolve();
    loads[0].reject(reason);
    await oldResult;
    const joined = cache.get('key');
    await Promise.resolve();
    assert.equal(loads.length, 2);
    loads[1].resolve('new');
    assert.equal(await fresh, 'new');
    assert.equal(await joined, 'new');
  });
}

test('repeated invalidations are distinct barriers without stored values', async () => {
  const { cache, loads } = fixture();
  const readers = [];
  for (let i = 0; i < 3; i++) {
    readers.push(cache.get('key'));
    await Promise.resolve();
    if (i < 2) cache.invalidate('key');
  }
  loads[1].resolve('middle');
  assert.equal(await readers[1], 'middle');
  loads[0].resolve('first');
  assert.equal(await readers[0], 'first');
  assert.equal(cache.size, 0);
  const joined = cache.get('key');
  await Promise.resolve();
  assert.equal(loads.length, 3);
  loads[2].resolve('last');
  assert.equal(await readers[2], 'last');
  assert.equal(await joined, 'last');
});

test('set wins without obsolete completion restarting its TTL', async () => {
  const { cache, loads, advance } = fixture(10);
  const old = cache.get('key');
  await Promise.resolve();
  advance(2);
  assert.equal(cache.set('key', undefined), undefined);
  advance(8);
  loads[0].resolve('old');
  assert.equal(await old, 'old');
  assert.equal(await cache.get('key'), undefined);
  advance(12);
  assert.equal(cache.size, 0);
  const fresh = cache.get('key');
  await Promise.resolve();
  assert.equal(loads.length, 2);
  loads[1].resolve('new');
  assert.equal(await fresh, 'new');
});

test('set expiration starts a fresh flight while obsolete load is pending', async () => {
